import json, re

d = json.load(open('/tmp/source_entries.json'))

# Build per-file: number -> entry text
def get_entry(key, n):
    return d[key].get(str(n))

# Extract URLs from an entry
def extract_urls(entry):
    if not entry: return []
    urls = re.findall(r'https?://[^\s\)\]]+', entry)
    # clean trailing punctuation
    out = []
    for u in urls:
        u = u.rstrip('.,;:')
        out.append(u)
    return out

# Verify sample
for key in ['materials','benchmarks','industry','challenges']:
    e = d[key].get('1')
    print(key, '1 ->', extract_urls(e))

# Parse draft markers with prefix inheritance
draft = open('solid-state-battery-electrolytes-draft.md').read()
groups = re.findall(r'\[([^\]]*?(?:materials|benchmarks|industry|challenges)[^\]]*?)\]', draft)

resolved = []
for g in groups:
    parts = [p.strip() for p in g.split(',')]
    toks = []
    cur_prefix = None
    for p in parts:
        m = re.match(r'^(materials|benchmarks|industry|challenges)-(\d+|gaps)$', p)
        if m:
            cur_prefix = m.group(1)
            toks.append((cur_prefix, m.group(2)))
        else:
            # bare number continuing same prefix, or range like 24-27 or 24–27
            m2 = re.match(r'^(\d+)[-–](\d+)$', p)
            if m2 and cur_prefix:
                a, b = int(m2.group(1)), int(m2.group(2))
                for n in range(a, b+1):
                    toks.append((cur_prefix, str(n)))
            elif re.match(r'^\d+$', p) and cur_prefix:
                toks.append((cur_prefix, p))
            else:
                toks.append(('?', p))
    resolved.append((g, toks))

# Check for any unresolved
bad = [t for g,toks in resolved for t in toks if t[0]=='?']
print('unresolved tokens:', bad[:10], 'count:', len(bad))

# Now resolve each token to entry
missing = []
for g, toks in resolved:
    for pref, n in toks:
        if n == 'gaps':
            continue
        if get_entry(pref, n) is None:
            missing.append(f'{pref}-{n}')
print('missing entries:', missing)

# Unique marker tokens used
used = set()
for g, toks in resolved:
    for pref, n in toks:
        if n != 'gaps':
            used.add((pref, n))
print('unique source tokens used:', len(used))
for pref in ['materials','benchmarks','industry','challenges']:
    nums = sorted(int(n) for p,n in used if p==pref)
    print(pref, len(nums), 'used; max', max(nums) if nums else 0)
EOF

