import json, re

d = json.load(open('/tmp/source_entries.json'))

def extract_urls(entry):
    if not entry: return []
    urls = re.findall(r'https?://[^\s\)\]]+', entry)
    return [u.rstrip('.,;:') for u in urls]

ALIASES = {
 'https://doi.org/10.1038/nmat3066': 'https://www.nature.com/articles/nmat3066',
 'https://ideas.repec.org/a/nat/natene/v1y2016i4d10.1038_nenergy.2016.30.html': 'https://doi.org/10.1038/nenergy.2016.30',
}
def canon(url):
    return ALIASES.get(url, url)

draft = open('solid-state-battery-electrolytes-draft.md').read()
groups = list(re.finditer(r'\[([^\]]*?(?:materials|benchmarks|industry|challenges)[^\]]*?)\]', draft))

def parse_group(g):
    parts = [p.strip() for p in g.split(',')]
    toks, cur = [], None
    for p in parts:
        m = re.match(r'^(materials|benchmarks|industry|challenges)-(\d+[a-z]?|gaps)$', p)
        if m:
            cur = m.group(1); toks.append((cur, m.group(2))); continue
        m2 = re.match(r'^(materials|benchmarks|industry|challenges)-(\d+)[-–](\d+)$', p)
        if m2:
            cur = m2.group(1)
            for n in range(int(m2.group(2)), int(m2.group(3))+1):
                toks.append((cur, str(n)))
            continue
        m3 = re.match(r'^(\d+)[-–](\d+)$', p)
        if m3 and cur:
            for n in range(int(m3.group(1)), int(m3.group(2))+1):
                toks.append((cur, str(n)))
            continue
        m4 = re.match(r'^(\d+[a-z]?)$', p)
        if m4 and cur:
            toks.append((cur, m4.group(1))); continue
        toks.append(('?', p))
    return toks

url_to_id, key_to_id, id_to_src = {}, {}, {}
gaps_markers = set()
for m in groups:
    for pref, num in parse_group(m.group(1)):
        if pref == '?':
            continue
        if num == 'gaps':
            gaps_markers.add(f'{pref}-gaps'); continue
        urls = extract_urls(d[pref].get(num, ''))
        if not urls:
            print('NO URL:', pref, num); continue
        u = canon(urls[0])
        if u not in url_to_id:
            new_id = len(url_to_id) + 1
            url_to_id[u] = new_id
            id_to_src[new_id] = {'pref': pref, 'num': num, 'url': u, 'entry': d[pref][num]}
        key_to_id[(pref, num)] = url_to_id[u]

print('unique sources:', len(url_to_id))
print('gaps markers:', sorted(gaps_markers))

json.dump({'url_to_id': url_to_id, 'key_to_id': {f'{p}-{n}': v for (p,n),v in key_to_id.items()},
           'id_to_src': {str(k): v for k,v in id_to_src.items()},
           'gaps': sorted(gaps_markers)},
          open('/tmp/mapping.json','w'), indent=1)

with open('/tmp/url_list.txt','w') as f:
    for i in range(1, len(url_to_id)+1):
        s = id_to_src[i]
        f.write(f'{i}\t{s["pref"]}-{s["num"]}\t{s["url"]}\n')
print('written /tmp/url_list.txt, total', len(url_to_id))
EOF

